package li.cil.oc.vm.simulated;

import java.util.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.atomic.AtomicReference;
import com.google.gson.*;import org.junit.Test;import static org.junit.Assert.*;
import li.cil.oc.api.vm.v2.*;import li.cil.oc.api.vm.v2.ProtocolV2.*;

/** Actual addon controller and codec, driven solely by memory transcripts. */
public class QmpFixtureTest {
 static final String CANVAS=String.join("",Collections.nCopies(64,"a"));
 static final String GREETING="{\"QMP\":{\"version\":{\"qemu\":{\"major\":9,\"minor\":0,\"micro\":0},\"package\":\"synthetic-not-a-qualified-build\"},\"capabilities\":[\"oob\"]}}\r\n";
 static byte[] bytes(String s){return s.getBytes(StandardCharsets.UTF_8);}
 interface Work {void run()throws Exception;}
 static void rejects(Class<? extends Throwable> type,Work work)throws Exception{try{work.run();fail("expected "+type);}catch(Throwable e){if(!type.isInstance(e))throw e;}}
 static final class H implements AutoCloseable {
  final boolean[] authorized={true};final Identity identity=new Identity(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID());
  final SessionV2 session=new SessionV2.Pool(32).open(identity,a->authorized[0],1,0,CANVAS,0);
  final MemoryQmpTransport io=new MemoryQmpTransport();final QmpFixtureController c=new QmpFixtureController(session,io,0);long sequence;
  byte[] wire(Operation op,UUID correlation,long seq){return bytes("{\"version\":2,\"session\":\""+session.id+"\",\"correlation\":\""+correlation+"\",\"world\":\""+identity.world+"\",\"case\":\""+identity.machine+"\",\"owner\":\""+identity.owner+"\",\"package\":\""+identity.pack+"\",\"generation\":1,\"sequence\":"+seq+",\"epoch\":0,\"canvas\":\""+CANVAS+"\",\"operation\":\""+op+"\"}");}
  QmpFixtureController.Result request(Operation op,long t){return c.submit(identity,wire(op,UUID.randomUUID(),++sequence),t);}
  List<JsonObject> requests(){List<JsonObject> list=new ArrayList<>();for(byte[] b:io.takeRequests())list.add(new JsonParser().parse(new String(b,StandardCharsets.UTF_8)).getAsJsonObject());return list;}
  void feed(String s,long t){io.feedFixture(bytes(s));c.pump(t);}
  void ack(JsonObject command,String body,long t){feed("{\"return\":"+body+",\"id\":\""+command.get("id").getAsString()+"\"}\r\n",t);}
  void negotiate(){feed(GREETING,0);assertEquals(QmpFixtureController.State.NEGOTIATING,c.state());List<JsonObject> q=requests();assertEquals(1,q.size());assertEquals("qmp_capabilities",q.get(0).get("execute").getAsString());assertFalse(q.get(0).has("arguments"));ack(q.get(0),"{}",0);assertEquals(QmpFixtureController.State.STOPPED,c.state());}
  void running(){negotiate();request(Operation.START,1);JsonObject q=requests().get(0);assertEquals("cont",q.get("execute").getAsString());ack(q,"{}",2);assertEquals(QmpFixtureController.State.STARTING,c.state());feed("{\"event\":\"RESUME\",\"data\":{},\"timestamp\":{\"seconds\":0,\"microseconds\":3}}\r\n",3);assertEquals(QmpFixtureController.State.RUNNING,c.state());}
  public void close(){c.close();}
 }
 @Test public void noAutoStartAndProductionProviderStaysOffline(){try(H h=new H()){assertTrue(h.io.takeRequests().isEmpty());assertEquals(QmpFixtureController.State.GREETING,h.c.state());assertEquals(QmpFixtureController.ResultCode.NOT_READY,h.request(Operation.START,0).code);assertTrue(h.io.takeRequests().isEmpty());assertEquals(0,h.session.pending());assertFalse(h.c.mayExecuteGuest());assertFalse(h.c.deletesData());assertTrue(h.c.simulated());assertTrue(new OCVMIntegrationSimulated.Provider2().openOffline(h.session) instanceof OfflineAdapterV2);}}
 @Test public void negotiationAndRunRequireSeparateObservations(){try(H h=new H()){h.running();assertFalse(h.c.mayExecuteGuest());assertTrue(h.c.pollResult().simulated);}}
 @Test public void fragmentedGreetingWorksAtEveryByte(){try(H h=new H()){byte[] wire=bytes(GREETING);for(byte b:wire){h.io.feedFixture(new byte[]{b});h.c.pump(0);}assertEquals(QmpFixtureController.State.NEGOTIATING,h.c.state());assertEquals(1,h.requests().size());}}
 @Test public void greetingAndCapabilityTimeoutAreBounded(){try(H h=new H()){h.c.pump(2000);assertEquals(QmpFixtureController.State.FAILED,h.c.state());assertTrue(h.c.requiresReconciliation());assertTrue(h.io.closed());}try(H h=new H()){h.feed(GREETING,0);h.requests();h.c.pump(2000);assertEquals(QmpFixtureController.State.FAILED,h.c.state());}}
 @Test public void duplicateGreetingFailsClosed(){try(H h=new H()){h.negotiate();h.feed(GREETING,1);assertEquals(QmpFixtureController.State.FAILED,h.c.state());assertEquals(0,h.c.pending());}}
 @Test public void gracefulStopWaitsForExitNotAcknowledgement(){try(H h=new H()){h.running();h.request(Operation.STOP,4);JsonObject q=h.requests().get(0);assertEquals("system_powerdown",q.get("execute").getAsString());h.ack(q,"{}",5);assertEquals(QmpFixtureController.State.STOPPING,h.c.state());assertTrue(h.requests().isEmpty());h.feed("{\"event\":\"SHUTDOWN\",\"data\":{\"guest\":true,\"reason\":\"guest-shutdown\"}}\r\n",6);assertEquals(QmpFixtureController.State.STOPPING,h.c.state());h.io.observeFixtureExit(0);h.c.pump(7);assertEquals(QmpFixtureController.State.STOPPED,h.c.state());assertFalse(h.c.requiresReconciliation());assertTrue(h.io.closed());}}
 @Test public void stopFallbackAndUncertainExitQuarantineWithoutDeleting(){try(H h=new H()){h.running();h.request(Operation.STOP,4);JsonObject power=h.requests().get(0);h.ack(power,"{}",5);h.c.pump(2004);JsonObject quit=h.requests().get(0);assertEquals("quit",quit.get("execute").getAsString());h.ack(quit,"{}",2005);h.c.pump(4004);assertEquals(QmpFixtureController.State.FAILED,h.c.state());assertTrue(h.c.requiresReconciliation());assertFalse(h.c.deletesData());}}
 @Test public void lateExitCannotUndoQuarantineDeadline(){try(H h=new H()){h.running();h.request(Operation.STOP,4);h.requests();h.io.observeFixtureExit(0);h.c.pump(5000);assertEquals(QmpFixtureController.State.FAILED,h.c.state());assertTrue(h.c.requiresReconciliation());}}
 @Test public void unexpectedExitIsNotSuccessfulStop(){for(int exit:new int[]{0,1,137})try(H h=new H()){h.running();h.io.observeFixtureExit(exit);h.c.pump(4);assertEquals(QmpFixtureController.State.FAILED,h.c.state());assertTrue(h.c.requiresReconciliation());}}
 @Test public void duplicatesDoNotExtendStopDeadline(){try(H h=new H()){h.running();h.request(Operation.STOP,4);JsonObject q=h.requests().get(0);h.ack(q,"{}",5);h.ack(q,"{}",1000);assertEquals(1,h.c.ignoredReplies());h.request(Operation.STOP,1001);assertTrue(h.requests().isEmpty());h.c.pump(2004);assertEquals("quit",h.requests().get(0).get("execute").getAsString());}}
 @Test public void unknownAndDuplicateReplyIdsDoNotChangeLifecycle(){try(H h=new H()){h.negotiate();h.feed("{\"return\":{},\"id\":\""+UUID.randomUUID()+"\"}\r\n",1);assertEquals(1,h.c.ignoredReplies());h.request(Operation.STATUS,2);JsonObject q=h.requests().get(0);h.ack(q,"{\"status\":\"paused\",\"running\":false,\"singlestep\":false}",3);h.ack(q,"{\"status\":\"running\"}",4);assertEquals(2,h.c.ignoredReplies());assertEquals(QmpFixtureController.State.STOPPED,h.c.state());}}
 @Test public void statusTimeoutDoesNotInventRunning(){try(H h=new H()){h.negotiate();h.request(Operation.STATUS,1);h.requests();h.c.pump(2001);assertEquals(QmpFixtureController.ResultCode.TIMEOUT,h.c.pollResult().code);assertEquals(QmpFixtureController.State.STOPPED,h.c.state());}}
 @Test public void startErrorsAndTimeoutQuarantine(){try(H h=new H()){h.negotiate();h.request(Operation.START,1);JsonObject q=h.requests().get(0);h.feed("{\"error\":{\"class\":\"GenericError\",\"desc\":\"fixture failure\"},\"id\":\""+q.get("id").getAsString()+"\"}\r\n",2);assertEquals(QmpFixtureController.State.FAILED,h.c.state());}try(H h=new H()){h.negotiate();h.request(Operation.START,1);h.requests();h.c.pump(2001);assertTrue(h.c.requiresReconciliation());}}
 @Test public void startAcknowledgementDoesNotRemoveRunningObservationDeadline(){try(H h=new H()){h.negotiate();h.request(Operation.START,1);JsonObject q=h.requests().get(0);h.ack(q,"{}",2);h.request(Operation.STATUS,1000);h.requests();h.c.pump(2001);assertEquals(QmpFixtureController.State.FAILED,h.c.state());assertTrue(h.c.requiresReconciliation());}}
 @Test public void pendingAndLifetimeCorrelationsAreBounded()throws Exception{try(H h=new H()){h.negotiate();for(int i=0;i<16;i++)assertEquals(QmpFixtureController.ResultCode.ACCEPTED,h.request(Operation.STATUS,1).code);assertEquals(16,h.c.pending());for(int i=16;i<128;i++)assertEquals(QmpFixtureController.ResultCode.LIMIT,h.request(Operation.STATUS,1).code);rejects(IllegalStateException.class,()->h.request(Operation.STATUS,1));assertEquals(16,h.requests().size());assertEquals(0,h.session.pending());}}
 @Test public void correlationReplayCannotCaptureAnotherRequest()throws Exception{try(H h=new H()){h.negotiate();UUID id=UUID.randomUUID();h.c.submit(h.identity,h.wire(Operation.STATUS,id,1),1);h.sequence=1;JsonObject q=h.requests().get(0);h.ack(q,"{\"status\":\"paused\"}",2);rejects(SecurityException.class,()->h.c.submit(h.identity,h.wire(Operation.STATUS,id,2),3));assertTrue(h.requests().isEmpty());assertEquals(QmpFixtureController.ResultCode.ACCEPTED,h.request(Operation.STATUS,3).code);}}
 @Test public void permissionRecheckedBeforeAnyTransportEffect()throws Exception{try(H h=new H()){h.negotiate();h.authorized[0]=false;rejects(SecurityException.class,()->h.request(Operation.START,1));assertTrue(h.io.closed());assertEquals(0,h.io.retainedChunks());assertEquals(QmpFixtureController.State.REVOKED,h.c.state());}}
 @Test public void malformedWireStaleLayoutAndForeignActorAreRejected()throws Exception{try(H h=new H()){h.negotiate();rejects(IllegalArgumentException.class,()->h.c.submit(h.identity,new byte[16385],1));byte[] stale=bytes(new String(h.wire(Operation.STATUS,UUID.randomUUID(),1),StandardCharsets.UTF_8).replace("\"generation\":1","\"generation\":2"));rejects(SecurityException.class,()->h.c.submit(h.identity,stale,1));assertTrue(h.requests().isEmpty());Identity foreign=new Identity(h.identity.world,h.identity.machine,UUID.randomUUID(),h.identity.pack);rejects(SecurityException.class,()->h.c.submit(foreign,h.wire(Operation.START,UUID.randomUUID(),1),2));assertTrue(h.io.closed());}}
 @Test public void idleExpiryAndRollbackRevoke()throws Exception{try(H h=new H()){h.negotiate();h.c.pump(30000);assertEquals(QmpFixtureController.State.REVOKED,h.c.state());}try(H h=new H()){h.negotiate();h.c.pump(10);rejects(SecurityException.class,()->h.c.pump(9));assertTrue(h.session.revoked());}}
 @Test public void dispatcherIsEnforced()throws Exception{try(H h=new H()){AtomicReference<Throwable> failure=new AtomicReference<>();Thread worker=new Thread(()->{try{h.c.pump(0);}catch(Throwable e){failure.set(e);}});worker.start();worker.join();assertTrue(failure.get() instanceof IllegalStateException);assertTrue(h.io.takeRequests().isEmpty());}}
 @Test public void resultRetentionIsBounded(){try(H h=new H()){h.negotiate();for(int i=0;i<20;i++){h.request(Operation.STATUS,i+1);JsonObject q=h.requests().get(0);h.ack(q,"{\"status\":\"paused\"}",i+1);}assertEquals(4,h.c.droppedResults());int count=0;while(h.c.pollResult()!=null)count++;assertEquals(16,count);}}
 @Test public void typedBridgeUsesExistingBudgetsAndReleasesOnRevoke()throws Exception{try(H h=new H()){FrameAssemblerV2.Budget budget=new FrameAssemblerV2.Budget(4096);GuestInputV2.Limiter limiter=new GuestInputV2.Limiter();SyntheticIoBridge b=new SyntheticIoBridge(h.c,budget,limiter,0);FrameAssemblerV2.Header f=new FrameAssemblerV2.Header(h.session.id,1,0,CANVAS,1,2,2,8,16);rejects(IllegalStateException.class,()->b.begin(h.identity,f,0));h.running();b.begin(h.identity,f,4);byte[] pixels=new byte[16];Arrays.fill(pixels,(byte)42);assertTrue(b.chunk(h.identity,f,0,pixels,4));byte[] copy=new byte[16];b.copy(h.identity,f,copy,4);assertArrayEquals(pixels,copy);b.focus(h.identity,4);b.offer(h.identity,h.session.id,1,0,CANVAS,GuestInputV2.Event.key(true,65),4);assertEquals(GuestInputV2.Kind.KEY_DOWN,b.pollInput().kind);h.session.revoke();assertEquals(0,budget.used());assertEquals(GuestInputV2.Kind.RELEASE_ALL,b.pollInput().kind);assertNull(b.pollInput());assertFalse(b.mayExecuteGuest());b.close();}}
 @Test public void bridgeRejectsStaleInputAndStopsOnPause()throws Exception{try(H h=new H()){h.running();SyntheticIoBridge b=new SyntheticIoBridge(h.c,new FrameAssemblerV2.Budget(4096),new GuestInputV2.Limiter(),3);b.focus(h.identity,4);rejects(SecurityException.class,()->b.offer(h.identity,h.session.id,2,0,CANVAS,GuestInputV2.Event.key(true,1),4));h.feed("{\"event\":\"STOP\",\"data\":{}}\r\n",5);assertEquals(QmpFixtureController.State.PAUSED,h.c.state());assertEquals(GuestInputV2.Kind.RELEASE_ALL,b.pollInput().kind);assertNull(b.pollInput());rejects(IllegalStateException.class,()->b.focus(h.identity,5));b.close();}}
}
